#ifndef ZEPHYR_SUBSYS_TESTSUITE_ZTEST_INCLUDE_ZTEST_TEST_H_
#define ZEPHYR_SUBSYS_TESTSUITE_ZTEST_INCLUDE_ZTEST_TEST_H_

#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/ztest_assert.h>
#include <zephyr/ztest_error_handler.h>
#include <zephyr/ztest_mock.h>
#include <zephyr/ztest_thread.h>

#ifdef __cplusplus
extern "C" {
#endif

#if defined(CONFIG_ZTEST_STACK_SIZE)
#define ZTEST_STACK_SIZE CONFIG_ZTEST_STACK_SIZE
#else
#define ZTEST_STACK_SIZE 1024
#endif

#if defined(CONFIG_ZTEST_DMEM_SIZE)
#define ZTEST_DMEM_SIZE CONFIG_ZTEST_DMEM_SIZE
#else
#define ZTEST_DMEM_SIZE 256
#endif

#if defined(CONFIG_ZTEST_BMEM_SIZE)
#define ZTEST_BMEM_SIZE CONFIG_ZTEST_BMEM_SIZE
#else
#define ZTEST_BMEM_SIZE 256
#endif

#if defined(CONFIG_ZTEST_TMEM_SIZE)
#define ZTEST_TMEM_SIZE CONFIG_ZTEST_TMEM_SIZE
#else
#define ZTEST_TMEM_SIZE 256
#endif

/* Test suite structure */
struct ztest_suite {
	const char *name;
	void (*test_suites_fn)(void);
	void (*setup_fn)(void);
	void (*teardown_fn)(void);
	void (*before_each_fn)(void);
	void (*after_each_fn)(void);
};

/* Test case structure */
struct ztest_unit_test {
	const char *name;
	void (*test_fn)(void);
	void (*setup_fn)(void);
	void (*teardown_fn)(void);
	void (*before_each_fn)(void);
	void (*after_each_fn)(void);
	bool run_once;
	bool is_failing;
};

/* Test fixture structure */
struct ztest_fixture {
	void (*setup)(void);
	void (*teardown)(void);
};

/* Test suite list */
extern struct ztest_suite __attribute__((weak)) ztest_suites[];

/* Test case list */
extern struct ztest_unit_test __attribute__((weak)) ztest_unit_tests[];

/* Test fixture list */
extern struct ztest_fixture __attribute__((weak)) ztest_fixtures[];

/* Test suite count */
extern size_t __attribute__((weak)) ztest_suites_cnt;

/* Test case count */
extern size_t __attribute__((weak)) ztest_unit_tests_cnt;

/* Test fixture count */
extern size_t __attribute__((weak)) ztest_fixtures_cnt;

/* Global test data */
extern struct k_sem ztest_sem;
extern struct k_thread ztest_thread;
extern k_tid_t ztest_thread_id;

/* Test thread stack */
ZTEST_THREAD_STACK_DEFINE(ztest_stack, ZTEST_STACK_SIZE);

/* Test data memory */
#if defined(CONFIG_USERSPACE)
K_APP_DMEM(ztest_dmem_area, ZTEST_DMEM_SIZE);
#define ZTEST_DMEM K_APP_DMEM_SECTION(ztest_dmem_area)
#else
__noinit __aligned(4) uint8_t ztest_dmem[ZTEST_DMEM_SIZE];
#define ZTEST_DMEM ztest_dmem
#endif

/* Test BSS memory */
#if defined(CONFIG_USERSPACE)
K_APP_BMEM(ztest_bmem_area, ZTEST_BMEM_SIZE);
#define ZTEST_BMEM K_APP_BMEM_SECTION(ztest_bmem_area)
#else
__noinit __aligned(4) uint8_t ztest_bmem[ZTEST_BMEM_SIZE];
#define ZTEST_BMEM ztest_bmem
#endif

/* Test memory */
#if defined(CONFIG_USERSPACE)
K_APP_DMEM(ztest_tmem_area, ZTEST_TMEM_SIZE);
#define ZTEST_TMEM K_APP_DMEM_SECTION(ztest_tmem_area)
#else
__noinit __aligned(4) uint8_t ztest_tmem[ZTEST_TMEM_SIZE];
#define ZTEST_TMEM ztest_tmem
#endif

/* Test suite registration macro */
#define ZTEST_SUITE(name, ...) \
	static void ztest_##name##_suites_fn(void); \
	static struct ztest_suite __used __section(".ztest_suites") \
		ztest_suite_##name = { \
		.name = #name, \
		.test_suites_fn = ztest_##name##_suites_fn, \
		__VA_ARGS__ \
	}; \
	static void ztest_##name##_suites_fn(void)

/* Test case registration macro */
#define ZTEST_UNIT_TEST(suite_name, test_name, ...) \
	static void ztest_##suite_name##_##test_name##_fn(void); \
	static struct ztest_unit_test __used __section(".ztest_unit_tests") \
		ztest_unit_test_##suite_name##_##test_name = { \
		.name = #test_name, \
		.test_fn = ztest_##suite_name##_##test_name##_fn, \
		__VA_ARGS__ \
	}; \
	static void ztest_##suite_name##_##test_name##_fn(void)

/* Test fixture registration macro */
#define ZTEST_FIXTURE(name, ...) \
	static struct ztest_fixture __used __section(".ztest_fixtures") \
		ztest_fixture_##name = { \
		__VA_ARGS__ \
	}; \
	static void ztest_##name##_setup(void);

/* Test setup/teardown macros */
#define ZTEST_SETUP(suite_name, fn) \
	static void ztest_##suite_name##_setup_fn(void) { fn(); }

#define ZTEST_TEARDOWN(suite_name, fn) \
	static void ztest_##suite_name##_teardown_fn(void) { fn(); }

#define ZTEST_BEFORE_EACH(suite_name, fn) \
	static void ztest_##suite_name##_before_each_fn(void) { fn(); }

#define ZTEST_AFTER_EACH(suite_name, fn) \
	static void ztest_##suite_name##_after_each_fn(void) { fn(); }

/* Test main function */
void ztest_main(void);

#ifdef __cplusplus
}
#endif

#endif /* ZEPHYR_SUBSYS_TESTSUITE_ZTEST_INCLUDE_ZTEST_TEST_H_ */
